/**
 * ===========================================================================
 * WHERE TO CHANGE THE HERO IMAGE
 * ===========================================================================
 *
 * YOU ALMOST CERTAINLY DO NOT EDIT THIS FILE BY HAND. Run one command:
 *
 *     npm run hero:image -- "C:\path\to\the-new-photo.jpg"
 *
 * That builds all four files, measures them, finds the lens, rewrites the
 * GENERATED block below, and writes a before/after preview PNG for you to
 * look at. It prints the path to that PNG when it finishes. Nothing else in
 * the repository needs editing — components/Hero.jsx reads this file and
 * only this file.
 *
 * Useful extras (all optional):
 *
 *     --add-iriz-wordmark      paste the `IRIZ` wordmark onto the front
 *                              panel, lifted from our own studio photograph.
 *                              OFF by default, because a real new photo of
 *                              the shipping unit already has it printed on
 *                              the product. Only turn this on for a frame
 *                              that is genuinely missing it.
 *     --lens 34.2%,46.5%       state the lens centre yourself instead of
 *                              letting the script look for it.
 *     --no-lens                no glow at all.
 *     --alt "…"                new alt text. Carried over from the block
 *                              below when you do not pass it.
 *     --dry-run                measure, detect and preview, write nothing.
 *
 * ---------------------------------------------------------------------------
 * WHAT IS HAND-WRITTEN HERE AND WHAT IS NOT
 * ---------------------------------------------------------------------------
 * `sizes` further down is HAND-WRITTEN and the script never touches it,
 * because it describes the PAGE LAYOUT, not the photograph — swapping the
 * picture does not move the breakpoints. Everything inside the GENERATED
 * block is a measurement of the files on disk and is rewritten on every run;
 * edits there are lost the next time the script runs. `alt` lives in the
 * generated block so `--alt` can set it, but it is carried forward untouched
 * when you do not pass that flag, so hand-editing it does survive.
 *
 * ---------------------------------------------------------------------------
 * WHY THE HERO IS A <picture> AND NOT next/image
 * ---------------------------------------------------------------------------
 * This is the page's LCP element, and on Cloudflare Workers `/_next/image` is
 * a Worker route backed by the Images binding — a billed transformation per
 * unique (source x width x format x quality), and a Worker invocation on a
 * request the edge could otherwise answer for free (see the next/image note
 * in CLAUDE.md). Pre-built static files cost neither, and they are already
 * inside the budget: ~53 KB of WebP for the whole hero.
 *
 * So the markup is a plain `<picture>` — WebP first, the JPEG as the fallback
 * source — each offering the pre-built widths through `srcset`, with the WebP
 * set preloaded as `type="image/webp"`, the token that stops a browser
 * WITHOUT WebP support from preloading a file it will then not use.
 */

/* --------------------------------------------------------------------- *
 * BEGIN GENERATED — npm run hero:image rewrites everything between these
 * two markers. Hand edits are overwritten on the next run, except `alt`,
 * which the script carries forward unless you pass --alt.
 * --------------------------------------------------------------------- */
export const HERO_IMAGE_BUILD = {
  /** The photograph this was built from, relative to the repo root. */
  source: 'design-src/product/flipkart-main-1664.jpg',
  /** When, so a stale asset can be told apart from a stale config. */
  builtAt: '2026-11-04',
  /** Was the `IRIZ` wordmark transplanted on? ('pasted' | 'none') */
  wordmark: 'pasted',
  /**
   * THE FILES ON DISK, widest first, written as LITERAL PATHS.
   *
   * Literal, not built from a stem and a width, and that is deliberate:
   * scripts/check-media.js finds asset paths with a regex over the source and
   * cannot follow a path assembled at runtime, so a template here would
   * quietly drop the hero out of the "every /media/ path exists" check. The
   * script writes these strings and the files they name in the same run, so
   * there is nothing for them to drift against.
   *
   * The widest keeps the bare name, so the <img>'s own `src` — the candidate
   * a browser with no `srcset` support falls back to — is a stable path that
   * does not move when another width is added.
   */
  files: [
    {
      width: 1400,
      webp: '/media/iriz/product/iriz-hero.webp',
      jpg: '/media/iriz/product/iriz-hero.jpg',
    },
    {
      width: 700,
      webp: '/media/iriz/product/iriz-hero-700.webp',
      jpg: '/media/iriz/product/iriz-hero-700.jpg',
    },
  ],
  /**
   * The real pixel size of the WIDEST file, passed to the <img> so the
   * browser reserves the right box before any bytes arrive. It is the
   * intrinsic RATIO as far as `srcset` is concerned, so every narrower
   * candidate reserves exactly the same box — which is what holds CLS at
   * zero whichever one the browser picks.
   */
  width: 1400,
  height: 991,
  /**
   * Where the projector's lens centre sits IN THIS FRAME, as a percentage of
   * the image box, so the glow in the hero can be placed without anyone
   * measuring the photograph again.
   *
   * `null` MEANS NO GLOW, and that is a supported state, not a failure. A
   * glow 8% off the glass looks like a bug in the page; no glow looks like a
   * design choice. So when `npm run hero:image` cannot find the lens with
   * confidence and nobody tells it where the lens is, it writes null here
   * and components/Hero.jsx renders no glow element at all.
   */
  lens: { x: '34.2%', y: '46.5%' },
  /**
   * NOT the same alt text as PRODUCT_SHOT, deliberately. The hero's <h1>
   * already announces "IRIZ mini projector for home" immediately before this
   * image, so repeating the product name here would have a screen reader say
   * it twice in a row. This describes what the PICTURE shows that the
   * heading does not.
   */
  alt: 'The IRIZ projector seen from the front, lens forward, on its folding stand',
};
/* --------------------------------------------------------------------- *
 * END GENERATED
 * --------------------------------------------------------------------- */

/** Widest first — the order the generated block is written in. */
const FILES = [...HERO_IMAGE_BUILD.files].sort((a, b) => b.width - a.width);
const WIDEST = FILES[0];

/**
 * Every built file, so "does the path this config names actually exist" stays
 * answerable from one list. Read by scripts/check-media.js's companion check
 * and by MEDIA in lib/iriz.js.
 */
export const HERO_IMAGE_FILES = FILES.flatMap(({ webp, jpg }) => [webp, jpg]);

function srcSetFor(ext) {
  // Ascending in the attribute — not required by the spec, but it is how
  // every example in it is written and how a reviewer expects to read it.
  return [...FILES]
    .sort((a, b) => a.width - b.width)
    .map((file) => `${file[ext]} ${file.width}w`)
    .join(', ');
}

/**
 * THE HOMEPAGE HERO'S PHOTOGRAPH, and everything the markup needs to place
 * it. Read by components/Hero.jsx — the preload in the <head>, the
 * <picture>'s WebP source, the <img> fallback and the lens glow all come
 * from here, so the four cannot drift apart.
 */
export const HERO_IMAGE = {
  src: WIDEST.webp,
  fallback: WIDEST.jpg,
  srcSet: srcSetFor('webp'),
  fallbackSrcSet: srcSetFor('jpg'),
  /*
   * HAND-WRITTEN, and the one field in this file that describes the LAYOUT
   * rather than the photograph. The script never rewrites it.
   *
   * It has to agree with the <picture>, the <img> fallback AND the <head>
   * preload — a preload whose `imageSizes` disagrees with the <img>'s
   * `sizes` downloads one candidate and then uses the other, which is worse
   * than no preload at all. Keeping it here is what makes that agreement
   * structural instead of remembered.
   *
   * The three breakpoints are read off the rendered layout, not guessed:
   *   >=1536px  the container is capped at 1440 and the card's image box
   *             measures 557px, so a vw unit would keep growing past what is
   *             drawn. A fixed 560px is the truth above the cap.
   *   >=1024px  the two-column grid starts; the image box is ~39vw.
   *   below     one column, full width inside the container and the card's
   *             own padding: ~88vw.
   */
  sizes: '(min-width: 1536px) 560px, (min-width: 1024px) 39vw, 88vw',
  width: HERO_IMAGE_BUILD.width,
  height: HERO_IMAGE_BUILD.height,
  alt: HERO_IMAGE_BUILD.alt,
  /** `null` when the lens was not located — see the note in the block above. */
  lens: HERO_IMAGE_BUILD.lens,
};
